insert into public.topics(id,course_id,title,description,emoji,position,is_active) values ('b2-psychology-relationships','b2-advanced','Психология и отношения','Точно описываем эмоции, мотивы и неоднозначные ситуации в отношениях','🧠',6,true) on conflict(id) do update set course_id=excluded.course_id,title=excluded.title,description=excluded.description,emoji=excluded.emoji,position=excluded.position,is_active=excluded.is_active;
insert into public.lessons(id,topic_id,kind,title,plan_title,subtitle,description,minutes,emoji,position,is_active,theory_title,theory_sections,source_metadata) values
('b2psych-words','b2-psychology-relationships','words','Słowa w kontekście','Новая лексика','8 карточек · B2','Точно описываем эмоции, мотивы и неоднозначные ситуации в отношениях',10,'🧠',198,true,'','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-grammar','b2-psychology-relationships','grammar','Jak to wyrazić?','Языковой фокус','6 заданий · B2','Оттенки модальности и оценки',13,'✏️',199,true,'Оттенки модальности и оценки','[["Степень уверенности","Наверняка: z pewnością / niewątpliwie; вероятно: prawdopodobnie / przypuszczalnie; осторожная гипотеза: być może / możliwe, że."],["Оценка поведения","Wydaje mi się rozsądne, że… оценивает решение мягче, чем To było nierozsądne. Конструкция mógł / mogła + infinitiv показывает упущенную возможность без прямого обвинения."],["Мотив и потребность","Zależało mu na…, obawiała się, że… и potrzebowała, żeby… связывают поступок с внутренней причиной, не выдавая догадку за факт."]]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-review','b2-psychology-relationships','review','Powtórka aktywna','Активное повторение','7 карточек · B2','Закрепи лексику темы',9,'🔄',200,true,'','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-quiz','b2-psychology-relationships','quiz','Quiz: Психология и отношения','Проверка темы','10 вопросов · B2','Проверь лексику и языковой фокус',10,'🎯',201,true,'','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-reading-check','b2-psychology-relationships','quiz','Czy rozumiesz tekst?','Понимание текста','6 вопросов · B2','Найди детали и главный вывод',8,'📖',202,true,'','[]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}')
insert into public.flashcards(id,polish,translation,example,position,is_active,source_metadata) values
('b2psych-1','odczuwać napięcie','чувствовать напряжение','Przed rozmową oboje odczuwali napięcie.',632,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-2','poczucie bezpieczeństwa','чувство безопасности','Szczerość buduje poczucie bezpieczeństwa.',633,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-3','potrzeba bliskości','потребность в близости','Każdy inaczej wyraża potrzebę bliskości.',634,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-4','wycofać się','отстраниться, выйти из ситуации','Paweł wycofał się z rozmowy, gdy emocje wzrosły.',635,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-5','okazać zrozumienie','проявить понимание','Warto najpierw okazać zrozumienie.',636,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-6','przypisywać komuś intencje','приписывать кому-то намерения','Nie należy przypisywać komuś intencji bez pytania.',637,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-7','reagować impulsywnie','реагировать импульсивно','Pod presją łatwiej reagować impulsywnie.',638,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-8','stawiać granice','устанавливать границы','Można stawiać granice bez odrzucania drugiej osoby.',639,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-9','mieć żal','обижаться, испытывать досаду','Miała żal, że nikt jej nie wysłuchał.',640,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-10','czuć się pominiętym','чувствовать себя обойдённым вниманием','Czuł się pominięty podczas podejmowania decyzji.',641,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-11','unikać konfrontacji','избегать конфронтации','Unikanie konfrontacji nie zawsze rozwiązuje problem.',642,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-12','wziąć odpowiedzialność','взять ответственность','Oboje wzięli odpowiedzialność za swoje słowa.',643,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-13','dojść do porozumienia','прийти к согласию','Po spokojnej rozmowie doszli do porozumienia.',644,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-14','prawdopodobnie','вероятно','Prawdopodobnie potrzebował czasu, żeby odpowiedzieć.',645,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}'),
('b2psych-15','z perspektywy','с точки зрения','Z jej perspektywy cisza oznaczała brak zainteresowania.',646,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30"}')
