insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('b2psych-grammar','Ola ___ poczuła się pominięta, ale nie znamy wszystkich okoliczności.','["prawdopodobnie","niewątpliwie na pewno","bez wątpienia zawsze"]',0,'Prawdopodobnie обозначает обоснованную, но не абсолютную уверенность.',0),
('b2psych-grammar','Z jego perspektywy rozsądne ___ odłożenie rozmowy do rana.','["wydawało się","dowiodło się","musiało zawsze"]',0,'Wydawało się передаёт субъективную оценку, а не установленный факт.',1),
('b2psych-grammar','Marta mogła ___ wcześniej, że potrzebuje chwili spokoju.','["powiedzieć","powiedziała","mówiąc"]',0,'Mogła + infinitiv показывает возможное, но не реализованное действие.',2),
('b2psych-grammar','Nie przypisuj mu intencji; ___ obawiał się reakcji grupy.','["być może","bezsprzecznie","na pewno zawsze"]',0,'Być może вводит осторожную гипотезу о мотиве.',3),
('b2psych-grammar','Составьте: Вероятно, она отстранилась, потому что боялась очередного конфликта.','["Prawdopodobnie wycofała się, ponieważ obawiała się kolejnego konfliktu.","Pewna wycofać, bo konflikt ją zawsze.","Wycofała prawdopodobny obawiając konfliktowi."]',0,'Prawdopodobnie смягчает вывод, а obawiać się требует родительного падежа.',4),
('b2psych-grammar','Составьте: С его точки зрения она могла проявить больше понимания.','["Z jego perspektywy mogła okazać więcej zrozumienia.","Jego perspektywa mogła okazała rozumienie więcej.","Według jego ona więcej zrozumieć mogła okazała."]',0,'Z perspektywy + родительный задаёт точку зрения; mogła + infinitiv — упущенную возможность.',5),
('b2psych-quiz','Co znaczy stawiać granice?','["ясно обозначать допустимое в отношениях","полностью прекращать общение","скрывать свои потребности"]',0,'Границы защищают потребности и не равны отвержению.',0),
('b2psych-quiz','Które słowo sygnalizuje ostrożną hipotezę?','["być może","niewątpliwie","bezsprzecznie"]',0,'Być może оставляет место неопределённости.',1),
('b2psych-quiz','Nie chcę ci ___ złych intencji.','["przypisywać","wycofywać","odczuwać się"]',0,'Естественное сочетание: przypisywać komuś intencje.',2),
('b2psych-quiz','Co pomaga uniknąć impulsywnej reakcji?','["nazwanie emocji i krótka przerwa","natychmiastowy zarzut","udawanie, że problemu nie ma"]',0,'Пауза и называние эмоции снижают напряжение.',3),
('b2psych-quiz','Kasia mogła powiedzieć to łagodniej oznacza, że…','["существовала другая возможность поведения","она точно ничего не сказала","говорить мягче было запрещено"]',0,'Mogła + infinitiv здесь оценивает упущенную возможность.',4),
('b2psych-quiz','Które zdanie nie przedstawia domysłu jako faktu?','["Prawdopodobnie zależało mu na uznaniu.","Na pewno chciał wszystkich zranić.","Jego motyw jest oczywisty."]',0,'Prawdopodobnie явно маркирует степень уверенности.',5),
('b2psych-quiz','Po szczerej rozmowie łatwiej ___.','["dojść do porozumienia","przypisać ciszę","odczuwać granicę"]',0,'Dojść do porozumienia — прийти к согласию.',6),
('b2psych-quiz','Czuła żal, ponieważ…','["jej potrzeba nie została zauważona","zawsze była spokojna","porozumienie już istniało"]',0,'Żal часто возникает из-за пережитой несправедливости или недостатка внимания.',7),
('b2psych-quiz','Jak brzmi najbardziej empatyczna reakcja?','["Rozumiem, że mogłeś poczuć się pominięty.","Przesadzasz jak zawsze.","Wiem lepiej, co naprawdę czujesz."]',0,'Первая реплика называет возможное чувство без навязывания интерпретации.',8),
('b2psych-quiz','Z jej perspektywy oznacza…','["с её точки зрения","по доказанному правилу","против её воли"]',0,'Выражение отделяет субъективное восприятие от общего факта.',9),
('b2psych-reading-check','Dlaczego Lena miała żal?','["Decyzje o wyjeździe zapadły bez niej","Michał odwołał wyjazd","Nie znała trasy powrotnej"]',0,'Она чувствовала себя исключённой из принятия решений.',0),
('b2psych-reading-check','Dlaczego Michał prawdopodobnie unikał konfrontacji?','["Obawiał się impulsywnej reakcji","Nie pamiętał wyjazdu","Nie zależało mu na Lenie"]',0,'Текст предлагает осторожную гипотезу о его страхе эскалации.',1),
('b2psych-reading-check','Jaką zasadę przyjęli?','["Najpierw obserwacja, potem emocje i potrzeby","Najpierw oskarżenie, potem cisza","Rozmowa tylko o faktach"]',0,'Их структура отделяет наблюдение от интерпретации.',2),
('b2psych-reading-check','Za co Michał wziął odpowiedzialność?','["Nie zapytał wcześniej o zdanie Leny","Sam wybrał cały wyjazd","Przerwał rozmowę na zawsze"]',0,'Он признал, что мог раньше включить Лену в решение.',3),
('b2psych-reading-check','Jaką granicę postawiła Lena?','["Chce uczestniczyć we wspólnych decyzjach","Nie będzie więcej podróżować","Nie chce słuchać wyjaśnień"]',0,'Граница касается совместных решений.',4),
('b2psych-reading-check','Po co używać ostrożnej modalności?','["Aby oddzielić fakty od interpretacji","Aby uniknąć odpowiedzialności","Aby ukryć wszystkie emocje"]',0,'Финал текста прямо формулирует эту функцию.',5);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('b2psych-rozmowa-po-nieudanym-wyjezdzie','b2-psychology-relationships','Rozmowa po nieudanym wyjeździe','Как отличить наблюдение от догадки о мотивах и восстановить диалог','B2',12,'🧠','["Po wspólnym wyjeździe Lena i Michał przez kilka dni rozmawiali wyłącznie o sprawach praktycznych. Lena miała żal, że podczas planowania większość decyzji zapadła bez niej. Michał natomiast odczuwał napięcie, ponieważ każdą próbę wyjaśnienia odbierał jako zapowiedź kolejnego konfliktu. Oboje potrzebowali bliskości, lecz każde z nich inaczej interpretowało ciszę drugiej osoby.","Lena początkowo przypisywała Michałowi obojętność. Z jej perspektywy wycofał się właśnie wtedy, gdy najbardziej potrzebowała wsparcia. Później uznała jednak, że była to tylko jedna z możliwych interpretacji. Michał prawdopodobnie unikał konfrontacji, bo obawiał się, że zareaguje impulsywnie. Nie oznaczało to, że jej uczucia były dla niego nieważne.","Podczas rozmowy ustalili zasadę: najpierw opisują to, co zauważyli, a dopiero potem mówią o emocjach i potrzebach. Lena powiedziała: «Kiedy wybraliście trasę beze mnie, poczułam się pominięta». Nie stwierdziła, że Michał celowo ją lekceważył. On odpowiedział: «Mogłem wcześniej zapytać o twoje zdanie. Potrzebowałem chwili spokoju, ale nie umiałem tego jasno powiedzieć».","Ta zmiana języka obniżyła napięcie. Michał okazał zrozumienie, a Lena postawiła granicę: chciała uczestniczyć w decyzjach, które dotyczą ich obojga. Jednocześnie wzięła odpowiedzialność za to, że wcześniej wypowiadała swoje przypuszczenia jak pewniki. Zamiast rozstrzygać, kto miał rację, próbowali zrozumieć, jakie potrzeby stały za ich reakcjami.","Nie doszli do porozumienia w każdej sprawie, lecz odzyskali poczucie bezpieczeństwa. Ich rozmowa pokazała, że ostrożna modalność nie służy unikaniu odpowiedzialności. Pozwala oddzielić fakty od interpretacji, dokładniej nazwać motywy i dać drugiej osobie przestrzeń na własne wyjaśnienie."]','{"zapadła":{"lemma":"zapaść","translation":"была принята","part_of_speech":"глагол"},"odczuwał":{"lemma":"odczuwać","translation":"чувствовал","part_of_speech":"глагол"},"napięcie":{"lemma":"napięcie","translation":"напряжение","part_of_speech":"существительное"},"odbierał":{"lemma":"odbierać","translation":"воспринимал","part_of_speech":"глагол"},"zapowiedź":{"lemma":"zapowiedź","translation":"предвестие","part_of_speech":"существительное"},"przypisywała":{"lemma":"przypisywać","translation":"приписывала","part_of_speech":"глагол"},"obojętność":{"lemma":"obojętność","translation":"равнодушие","part_of_speech":"существительное"},"wycofał":{"lemma":"wycofać się","translation":"отстранился","part_of_speech":"глагол"},"unikał":{"lemma":"unikać","translation":"избегал","part_of_speech":"глагол"},"konfrontacji":{"lemma":"konfrontacja","translation":"конфронтации","part_of_speech":"существительное"},"obawiał":{"lemma":"obawiać się","translation":"опасался","part_of_speech":"глагол"},"zauważyli":{"lemma":"zauważyć","translation":"заметили","part_of_speech":"глагол"},"pominięta":{"lemma":"pominąć","translation":"обойдённая вниманием","part_of_speech":"причастие"},"lekceważył":{"lemma":"lekceważyć","translation":"пренебрегал","part_of_speech":"глагол"},"obniżyła":{"lemma":"obniżyć","translation":"снизила","part_of_speech":"глагол"},"przypuszczenia":{"lemma":"przypuszczenie","translation":"предположения","part_of_speech":"существительное"},"pewniki":{"lemma":"pewnik","translation":"неоспоримые факты","part_of_speech":"существительное"},"rozstrzygać":{"lemma":"rozstrzygać","translation":"решать однозначно","part_of_speech":"глагол"},"odzyskali":{"lemma":"odzyskać","translation":"вернули","part_of_speech":"глагол"},"modalność":{"lemma":"modalność","translation":"модальность","part_of_speech":"существительное"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"b2psych-reading-check"}',42,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
